const SW_BENCHMARK={year:2025,published:'2026-08-07',checked:'2026-10-12',organization:{total:509.1,rows:[['기술/사업부문',242.4],['운영',86.9],['영업/마케팅',57.9],['연구소',53.8],['경영지원/전략기획',51.4],['고객지원 서비스',16.7]]},career:{total:399.8,rows:[['15년 이상',24.8],['10~15년 미만',57.5],['5~10년 미만',120.4],['3~5년 미만',138.4],['3년 미만',58.8]]},source:'https://spri.kr/posts/view/24012?code=stat_sw_software_reports',pdf:'https://spri.kr/download/23884',middleSource:'https://mesis.or.kr/usr/db/M01/01/list.do',wageSource:'https://www.wagework.go.kr/pt/c/a/retrieveClsfWageSrch.do?pageId=PT07020000&topPageId=PT07000000'};
function benchmarkSalary(size){const defaults=['임원','부장','차장','과장','대리','주임','사원'];const ranks=[...new Set([...defaults,...P.ranks(data().cur,state.date).map(r=>r.rank).filter(r=>r!=='미입력')])];return `<div class="reference-unavailable"><span class="reference-status unavailable">확인불가</span><p>IT 업종 × ${size} × 회사 직급별 평균연봉의 일치하는 공개 수치를 확인하지 못했습니다.</p></div><div class="tablewrap"><table class="reference-salary"><thead><tr><th>직급</th><th>외부 평균연봉</th></tr></thead><tbody>${ranks.map(rank=>`<tr><td>${esc(rank)}</td><td><span class="reference-status unavailable">확인불가</span></td></tr>`).join('')}</tbody></table></div><p class="benchmark-note">임금직업포털은 직군·직급단계 중심의 추정치이고 상용근로자 100인 이상 사업체를 대상으로 합니다. 사업체 인원 규모는 중소·중견기업 구분과 다릅니다. 우리 회사 직급과 정확히 대응되는 값을 확인하기 전까지 표시할 수 없습니다.</p><p class="source-line">확인일 ${SW_BENCHMARK.checked} · <a href="${SW_BENCHMARK.wageSource}" target="_blank" rel="noopener">임금직업포털 기준 확인</a></p>`;}
function benchmarkUnavailable(kind){const label=kind==='career'?'경력별 인원 비중':'조직·직군별 인원 비중';return `<div class="reference-unavailable"><span class="reference-status unavailable">확인불가</span><h3>IT 중견기업 ${label}</h3><p>확인한 공개 원문에서 중견기업으로 별도 구분된 해당 수치를 확인하지 못했습니다.</p></div><p class="benchmark-note">SPRi 인력표의 기업규모 구분은 대기업·중소기업입니다. 대기업 구분을 중견기업 수치로 치환할 수 없습니다. 중견기업통계의 업종별 기업·종사자 총계는 조직별·경력별 분포를 설명하지 않습니다.</p><p class="source-line">확인일 ${SW_BENCHMARK.checked}<br><a href="${SW_BENCHMARK.source}" target="_blank" rel="noopener">SPRi 분류 확인</a> · <a href="${SW_BENCHMARK.middleSource}" target="_blank" rel="noopener">중견기업 공개통계 확인</a></p>`;}
function benchmarkPanel(){const kind=state.benchmark,size=state.benchmarkSize==='middle'?'중견기업':'중소기업',career=kind==='career',d=career?SW_BENCHMARK.career:SW_BENCHMARK.organization;const known=kind!=='salary'&&state.benchmarkSize!=='middle';let content;if(kind==='salary')content=benchmarkSalary(size);else if(!known)content=benchmarkUnavailable(kind);else content=`<div class="reference-verified"><span class="reference-status verified">출처 확인</span><span>2025년 SW ${size} 인력 통계</span></div><div class="horizontal">${d.rows.map(([label,n])=>`<div class="barrow"><span>${label}</span><div class="track"><div class="fill benchmark-fill" style="width:${n/d.total*100}%"></div></div><span class="barvalue">${pct(n,d.total)}</span></div>`).join('')}</div><p class="benchmark-note">${career?'SW 전문인력 399.8천 명 기준입니다. 업계 전체 경력이며 현재 회사 근속과 다릅니다. 반올림으로 항목 합계와 총계에 차이가 있습니다.':'SW부문 인력 509.1천 명 기준입니다. 공식 조직 분류이므로 우리 회사 직군과 동일한 분류가 아닙니다. 비중은 공표 인원에서 계산했습니다.'}</p><p class="source-line">2025년 기준 · 2026.08.07 게시 · 보고서 ${career?'25':'22'}쪽<br><a href="${SW_BENCHMARK.source}" target="_blank" rel="noopener">SPRi 원문</a> · <a href="${SW_BENCHMARK.pdf}#page=${career?37:34}" target="_blank" rel="noopener">통계표 확인</a> · 확인일 ${SW_BENCHMARK.checked}</p>`;return `<section class="panel benchmark-panel">${head('IT 업계 참고자료','외부 공표 통계 및 확인 상태',size)}<div class="reference-callout"><b>외부 참고자료</b><span>회사 인사자료와 구분되는 외부 통계입니다. 조사 대상과 분류 기준을 확인해 참고하세요. 불명확한 항목은 확인불가로 표시합니다.</span></div><div class="benchmark-sizes" role="group" aria-label="참고자료 기업 구분"><button data-benchmark-size="sme" aria-pressed="${state.benchmarkSize!=='middle'}" class="${state.benchmarkSize!=='middle'?'selected':''}">중소기업</button><button data-benchmark-size="middle" aria-pressed="${state.benchmarkSize==='middle'}" class="${state.benchmarkSize==='middle'?'selected':''}">중견기업</button></div><div class="benchmark-tabs" role="group" aria-label="참고자료 항목"><button data-benchmark="organization" aria-pressed="${kind==='organization'}" class="${kind==='organization'?'selected':''}">조직별 구성</button><button data-benchmark="career" aria-pressed="${career}" class="${career?'selected':''}">경력별 구성</button><button data-benchmark="salary" aria-pressed="${kind==='salary'}" class="${kind==='salary'?'selected':''}">직급별 평균임금</button></div><div class="benchmark-result" aria-live="polite">${content}</div></section>`;}
